import numpy as np
from scipy import stats

MAX_DRIVERS = 4

def design(feats):
    # Filter out derived features for driver selection
    non_derived_ids = [fid for fid, t in zip(feats.ids, feats.types) if t != 'derived']

    # Calculate effect sizes using mean difference
    effect_sizes = []
    for i, fid in enumerate(non_derived_ids):
        col_idx = feats.column(fid)
        y0_mean = np.mean(feats.x[feats.y == 0, col_idx])
        y1_mean = np.mean(feats.x[feats.y == 1, col_idx])
        effect_sizes.append(abs(y1_mean - y0_mean))

    # Select top features by effect size
    sorted_indices = np.argsort(effect_sizes)[::-1]
    # Take at most MAX_DRIVERS features with substantial effect size
    driver_candidates = []
    for i in sorted_indices:
        if len(driver_candidates) >= MAX_DRIVERS:
            break
        if effect_sizes[i] > 0.1:
            driver_candidates.append(non_derived_ids[i])

    drivers = tuple(driver_candidates)

    # Build columns list avoiding near-duplicates
    columns = list(drivers)
    seen = set(drivers)

    # Add correlated features to columns but not as drivers
    correlations = {}
    for i, fid1 in enumerate(non_derived_ids):
        for j, fid2 in enumerate(non_derived_ids[:i]):
            if abs(np.corrcoef(feats.x[:, feats.column(fid1)], feats.x[:, feats.column(fid2)])[0,1]) >= 0.6:
                correlations[(fid1, fid2)] = True

    # Add correlated features to columns if they're not already there
    for (fid1, fid2) in correlations:
        if fid1 in drivers and fid2 not in seen:
            columns.append(fid2)
            seen.add(fid2)
        elif fid2 in drivers and fid1 not in seen:
            columns.append(fid1)
            seen.add(fid1)

    # For products, consider top features with high correlation
    products = []
    if len(drivers) >= 2:
        # Add product terms between top drivers
        for i in range(min(2, len(drivers))):
            for j in range(i+1, min(3, len(drivers))):
                products.append((drivers[i], drivers[j]))

    # Simple weighted score: sum of top drivers
    loadings = {fid: 1.0 for fid in drivers}

    return Design(
        drivers=drivers,
        columns=tuple(columns),
        products=tuple(products),
        loadings=loadings
    )

